import s32_pkg::*;

`default_nettype none

// d2_controls (D2-play): Pocket cont1_key[15:0] (APF, clk_74a domain, active HIGH): 0 up, 1 down, 2 left, 3 right, 4 A, 5 B,
// 6 X, 7 Y, 8 L1, 9 R1, 10 L2, 11 R2, 12 L3, 13 R3, 14 select, 15 start. Two-flop synchroniser into clk (levels, no pulses: a
// held key is a held level; the game debounces its own coin switch). GA2 ports are active LOW and follow MAME ga2u:
//   p1a   (C00000): b0 attack(A), b1 jump(B), b2 magic(X or Y), b3 unused(1), b4 down, b5 up, b6 right, b7 left (upstream p_dig order)
//   svc12 (C00008): b4 Start1 (start); b0 service, b1 test, b2/b3 COIN4/COIN3, b5 Start2, b6/b7 stay released
//   ppi_pc(C00064): b3 Coin1 (select; ga2u US set). Upper nibble stays 0 (D2's previous constant 8'h0F), bits 2:0 released.
// Coin: upstream (Arcade-SegaSystem32.sv l.856-862, 898) also drives svc12 bit2 from the same button; MAME ga2u counts that line
// as a SECOND coin (COIN4), so only the ppi_pc bit is driven here (README "D2-play", MAME double-coin test).
// Idle (no key): p1a = svc12 = FF, ppi_pc = 0F, exactly the previous constants.
// 2P (exp/audio3-2p): key2 = Pocket cont2_key[15:0] (Dock controller 2), the same button layout and synchroniser, drives MAME ga2u
//   p2a   (C00002, P2_A): the p1a layout; svc12 b5 Start2 (start); ppi_pc b2 Coin2 (select; EXTRA3 COIN2 of the US set).
// 4P (exp/audio3-4p): key3 / key4 = Pocket cont3_key / cont4_key [15:0] (Dock controllers 3 / 4), the same layout and synchroniser:
//   ppa / ppb (8255 port A / B = MAME EXTRA1 / EXTRA2 = P3 / P4): the p1a layout; ppi_pc b0 Start3 / b1 Start4 (start);
//   svc12 b3 Coin 3 / b2 Coin 4 (select; ga2u SERVICE12 COIN3 / COIN4). Idle (no key2-4): p2a = ppa = ppb = FF, svc12 / ppi_pc as 1P.
// u1_controls (release/s32-v1, rel_derive.py K): d2_controls with the input-wiring profile of the configuration file and the resume
// input guard. Keys as d2_controls (Pocket contN_key, APF, clk_74a, active HIGH: 0 up, 1 down, 2 left, 3 right, 4 A, 5 B, 6 X, 7 Y,
// 14 select, 15 start), two-flop synchronised into clk; the same per-pad player layout for players 1-4 (pdig).
//   profile 0 = GA2 US wiring, exactly GA2 RC1's d2_controls (MAME ga2u; AU3_2P / AU3_4P): p2a = P2, ppa / ppb = P3 / P4;
//     svc12 b4 Start1, b5 Start2, b3 Coin3, b2 Coin4; ppi_pc b3 Coin1, b2 Coin2, b0 Start3, b1 Start4.
//   profile 1 = World wiring, exactly SpidAudio1-4P's (MAME spidman; sa_derive.py E): ports 2-4 count only while their type field
//     (key[31:28]) is 2 or 3 (docked game controller); svc12 b4 Start1, b5 Start2, b2 Coin1 (P1 / P3 select), b3 Coin2 (P2 / P4
//     select); ppi_pc b0 Start3, b1 Start4, b3:2 released.
// Guard (sa_derive.py G, every profile): hold = pause_r. Every key reads released while paused, and a key held at any time during
// a pause stays masked after the resume until it reads released (g <= hold ? g | k : g & k; output k & ~g). Never paused => every
// g stays 0 and the outputs equal the profile's own line. Idle (no key): p1a = p2a = ppa = ppb = svc12 = FF, ppi_pc = 0F.
module u1_controls (
    input  wire        clk,
    input  wire [15:0] key,
    input  wire [31:0] key2, key3, key4,
    input  wire  [1:0] profile,      // 0: GA2 US (ga2u) wiring; 1: World wiring (spidman)
    input  wire        hold,         // pause: keys held during a pause stay masked after it until released
    output wire  [7:0] p1a, p2a, ppa, ppb, svc12, ppi_pc
);
    reg  [15:0] key_m = 16'd0, key_s = 16'd0;
    reg  [19:0] k2_m = 20'd0, k2_s = 20'd0, k3_m = 20'd0, k3_s = 20'd0, k4_m = 20'd0, k4_s = 20'd0;   // {type, keys}
always @(posedge clk) begin
    key_m <= key; key_s <= key_m;
    k2_m <= {key2[31:28], key2[15:0]}; k2_s <= k2_m;
    k3_m <= {key3[31:28], key3[15:0]}; k3_s <= k3_m;
    k4_m <= {key4[31:28], key4[15:0]}; k4_s <= k4_m;
end
    wire        world = profile[0];
    function automatic [15:0] pad(input [19:0] k, input gate);   // World: only a docked game controller (type 2 / 3) counts
        pad = (!gate || k[19:16] == 4'd2 || k[19:16] == 4'd3) ? k[15:0] : 16'd0;
    endfunction
    function automatic [7:0] pdig(input [15:0] k);   // player port (P1_A layout), active low; X or Y = the third button
        pdig = ~{k[2], k[3], k[0], k[1], 1'b0, k[6] | k[7], k[5], k[4]};
    endfunction
    wire [15:0] r1 = key_s, r2 = pad(k2_s, world), r3 = pad(k3_s, world), r4 = pad(k4_s, world);
    reg  [15:0] g1 = 16'd0, g2 = 16'd0, g3 = 16'd0, g4 = 16'd0;   // resume guard
always @(posedge clk) begin
    g1 <= hold ? (g1 | r1) : (g1 & r1);
    g2 <= hold ? (g2 | r2) : (g2 & r2);
    g3 <= hold ? (g3 | r3) : (g3 & r3);
    g4 <= hold ? (g4 | r4) : (g4 & r4);
end
    wire [15:0] q1 = r1 & ~g1 & {16{~hold}}, q2 = r2 & ~g2 & {16{~hold}}, q3 = r3 & ~g3 & {16{~hold}}, q4 = r4 & ~g4 & {16{~hold}};
assign p1a    = pdig(q1);
assign p2a    = pdig(q2);
assign ppa    = pdig(q3);
assign ppb    = pdig(q4);
assign svc12  = world ? ~{2'b00, q2[15], q1[15], q2[14] | q4[14], q1[14] | q3[14], 2'b00}
                      : ~{2'b00, q2[15], q1[15], q3[14], q4[14], 2'b00};
assign ppi_pc = world ? {4'h0, 2'b11, ~q4[15], ~q3[15]}
                      : {4'h0, ~q1[14], ~q2[14], ~q4[15], ~q3[15]};
endmodule
// u1_cfg_reg (release/s32-v1, rel_derive.py R): u1_board_cfg's consumed outputs, registered in clk_sys (one stage, one edge for all).
module u1_cfg_reg (
    input  wire       clk,
    input  wire       ok_c, v25_c, ppi_c, sprv_c,
    input  wire [1:0] sprm_c, prof_c,
    output reg        ok = 1'b0, v25 = 1'b0, ppi = 1'b0, sprv = 1'b0,
    output reg  [1:0] sprm = 2'd0, prof = 2'd0
);
always @(posedge clk) begin ok <= ok_c; v25 <= v25_c; ppi <= ppi_c; sprv <= sprv_c; sprm <= sprm_c; prof <= prof_c; end
endmodule


module core_top #(
    parameter int          CE_MODE         = 1,          // 1: upstream ce accumulator (hardware cadence), 0: exact 1/3
    parameter int          RD_EDGES        = 3,          // SRAM read sample: clk_sys edges after the address edge (62 ns)
    parameter int unsigned VIDEO_AFTER_RST = 297192,     // clk_sys from CPU-reset release to video-reset release (S2)
    parameter int          BAND_EN         = 0,          // on-screen diagnostic band (RC1: off = the full game picture)
    parameter int          BAND_ROW0       = 220,        // first of the band's four DE lines
    parameter int          HB_BIT          = 18,         // heartbeat = this bit of the work-RAM access counter
    parameter [31:0]       EXP_UNUSED = 32'd0     // U1: the band's expected slot sums come from the configuration file (rel: none for slot 7)
) (

//
// physical connections
//

///////////////////////////////////////////////////
// clock inputs 74.25mhz. not phase aligned, so treat these domains as asynchronous

input   wire            clk_74a, // mainclk1
input   wire            clk_74b, // mainclk1 

///////////////////////////////////////////////////
// cartridge interface
// switches between 3.3v and 5v mechanically
// output enable for multibit translators controlled by pic32

// GBA AD[15:8]
inout   wire    [7:0]   cart_tran_bank2,
output  wire            cart_tran_bank2_dir,

// GBA AD[7:0]
inout   wire    [7:0]   cart_tran_bank3,
output  wire            cart_tran_bank3_dir,

// GBA A[23:16]
inout   wire    [7:0]   cart_tran_bank1,
output  wire            cart_tran_bank1_dir,

// GBA [7] PHI#
// GBA [6] WR#
// GBA [5] RD#
// GBA [4] CS1#/CS#
//     [3:0] unwired
inout   wire    [7:4]   cart_tran_bank0,
output  wire            cart_tran_bank0_dir,

// GBA CS2#/RES#
inout   wire            cart_tran_pin30,
output  wire            cart_tran_pin30_dir,
// when GBC cart is inserted, this signal when low or weak will pull GBC /RES low with a special circuit
// the goal is that when unconfigured, the FPGA weak pullups won't interfere.
// thus, if GBC cart is inserted, FPGA must drive this high in order to let the level translators
// and general IO drive this pin.
output  wire            cart_pin30_pwroff_reset,

// GBA IRQ/DRQ
inout   wire            cart_tran_pin31,
output  wire            cart_tran_pin31_dir,

// infrared
input   wire            port_ir_rx,
output  wire            port_ir_tx,
output  wire            port_ir_rx_disable, 

// GBA link port
inout   wire            port_tran_si,
output  wire            port_tran_si_dir,
inout   wire            port_tran_so,
output  wire            port_tran_so_dir,
inout   wire            port_tran_sck,
output  wire            port_tran_sck_dir,
inout   wire            port_tran_sd,
output  wire            port_tran_sd_dir,
 
///////////////////////////////////////////////////
// cellular psram 0 and 1, two chips (64mbit x2 dual die per chip)

output  wire    [21:16] cram0_a,
inout   wire    [15:0]  cram0_dq,
input   wire            cram0_wait,
output  wire            cram0_clk,
output  wire            cram0_adv_n,
output  wire            cram0_cre,
output  wire            cram0_ce0_n,
output  wire            cram0_ce1_n,
output  wire            cram0_oe_n,
output  wire            cram0_we_n,
output  wire            cram0_ub_n,
output  wire            cram0_lb_n,

output  wire    [21:16] cram1_a,
inout   wire    [15:0]  cram1_dq,
input   wire            cram1_wait,
output  wire            cram1_clk,
output  wire            cram1_adv_n,
output  wire            cram1_cre,
output  wire            cram1_ce0_n,
output  wire            cram1_ce1_n,
output  wire            cram1_oe_n,
output  wire            cram1_we_n,
output  wire            cram1_ub_n,
output  wire            cram1_lb_n,

///////////////////////////////////////////////////
// sdram, 512mbit 16bit

output  wire    [12:0]  dram_a,
output  wire    [1:0]   dram_ba,
inout   wire    [15:0]  dram_dq,
output  wire    [1:0]   dram_dqm,
output  wire            dram_clk,
output  wire            dram_cke,
output  wire            dram_ras_n,
output  wire            dram_cas_n,
output  wire            dram_we_n,

///////////////////////////////////////////////////
// sram, 1mbit 16bit

output  wire    [16:0]  sram_a,
inout   wire    [15:0]  sram_dq,
output  wire            sram_oe_n,
output  wire            sram_we_n,
output  wire            sram_ub_n,
output  wire            sram_lb_n,

///////////////////////////////////////////////////
// vblank driven by dock for sync in a certain mode

input   wire            vblank,

///////////////////////////////////////////////////
// i/o to 6515D breakout usb uart

output  wire            dbg_tx,
input   wire            dbg_rx,

///////////////////////////////////////////////////
// i/o pads near jtag connector user can solder to

output  wire            user1,
input   wire            user2,

///////////////////////////////////////////////////
// RFU internal i2c bus 

inout   wire            aux_sda,
output  wire            aux_scl,

///////////////////////////////////////////////////
// RFU, do not use
output  wire            vpll_feed,


//
// logical connections
//

///////////////////////////////////////////////////
// video, audio output to scaler
output  wire    [23:0]  video_rgb,
output  wire            video_rgb_clock,
output  wire            video_rgb_clock_90,
output  wire            video_de,
output  wire            video_skip,
output  wire            video_vs,
output  wire            video_hs,
    
output  wire            audio_mclk,
input   wire            audio_adc,
output  wire            audio_dac,
output  wire            audio_lrck,

///////////////////////////////////////////////////
// bridge bus connection
// synchronous to clk_74a
output  wire            bridge_endian_little,
input   wire    [31:0]  bridge_addr,
input   wire            bridge_rd,
output  reg     [31:0]  bridge_rd_data,
input   wire            bridge_wr,
input   wire    [31:0]  bridge_wr_data,

///////////////////////////////////////////////////
// controller data
// 
// key bitmap:
//   [0]    dpad_up
//   [1]    dpad_down
//   [2]    dpad_left
//   [3]    dpad_right
//   [4]    face_a
//   [5]    face_b
//   [6]    face_x
//   [7]    face_y
//   [8]    trig_l1
//   [9]    trig_r1
//   [10]   trig_l2
//   [11]   trig_r2
//   [12]   trig_l3
//   [13]   trig_r3
//   [14]   face_select
//   [15]   face_start
//   [31:28] type
// joy values - unsigned
//   [ 7: 0] lstick_x
//   [15: 8] lstick_y
//   [23:16] rstick_x
//   [31:24] rstick_y
// trigger values - unsigned
//   [ 7: 0] ltrig
//   [15: 8] rtrig
//
input   wire    [31:0]  cont1_key,
input   wire    [31:0]  cont2_key,
input   wire    [31:0]  cont3_key,
input   wire    [31:0]  cont4_key,
input   wire    [31:0]  cont1_joy,
input   wire    [31:0]  cont2_joy,
input   wire    [31:0]  cont3_joy,
input   wire    [31:0]  cont4_joy,
input   wire    [15:0]  cont1_trig,
input   wire    [15:0]  cont2_trig,
input   wire    [15:0]  cont3_trig,
input   wire    [15:0]  cont4_trig
    
);



// ============================================================================================ safe defaults (HW-001)
assign port_ir_tx = 0;
assign port_ir_rx_disable = 1;
assign bridge_endian_little = 0;

assign cart_tran_bank3 = 8'hzz;   assign cart_tran_bank3_dir = 1'b0;
assign cart_tran_bank2 = 8'hzz;   assign cart_tran_bank2_dir = 1'b0;
assign cart_tran_bank1 = 8'hzz;   assign cart_tran_bank1_dir = 1'b0;
assign cart_tran_bank0 = 4'hf;    assign cart_tran_bank0_dir = 1'b1;
assign cart_tran_pin30 = 1'b0;    assign cart_tran_pin30_dir = 1'bz;
assign cart_pin30_pwroff_reset = 1'b0;
assign cart_tran_pin31 = 1'bz;    assign cart_tran_pin31_dir = 1'b0;
assign port_tran_so = 1'bz;       assign port_tran_so_dir = 1'b0;
assign port_tran_si = 1'bz;       assign port_tran_si_dir = 1'b0;
assign port_tran_sck = 1'bz;      assign port_tran_sck_dir = 1'b0;
assign port_tran_sd = 1'bz;       assign port_tran_sd_dir = 1'b0;

// AU: cram0 is driven by d2_wave_psram (the RF5C68 wave RAM); AU3: cram1 by d2_rom_psram (the Z80 sound ROM); both below.

assign dbg_tx = 1'bZ;  assign user1 = 1'bZ;  assign aux_scl = 1'bZ;  assign vpll_feed = 1'bZ;
// AU: audio_mclk / audio_lrck / audio_dac are driven by sound_i2s (below).

// ============================================================================================ clocks
// One PLL, phase-aligned outputs (mf_pll_ga2.v). clk_sys = clk_ram/2 and clk_vid = clk_sys/4 are SYNCHRONOUS to clk_ram
// (the load queue, the reset release and ga2_video's /4 transfer rely on it); clk_v25 is treated as asynchronous by the
// upstream SDC (the V25 crossings are synchronised in s32_core); clk_74a is asynchronous to all of them.
    wire clk_ram, clk_sys, clk_v25, clk_vid, clk_vid_90, pll_locked;
mf_pll_ga2 mp (
    .refclk(clk_74a), .rst(1'b0),
    .outclk_0(clk_ram), .outclk_1(clk_sys), .outclk_2(clk_v25), .outclk_3(clk_vid), .outclk_4(clk_vid_90),
    .locked(pll_locked));

    wire pll_locked_74;
synch_3 s_lock74 (pll_locked, pll_locked_74, clk_74a);
    reg [1:0] lock_ram = 2'b00, lock_sys = 2'b00;
always @(posedge clk_ram) lock_ram <= {lock_ram[0], pll_locked};
always @(posedge clk_sys) lock_sys <= {lock_sys[0], pll_locked};
    wire locked_r = lock_ram[1], locked_s = lock_sys[1];

// ============================================================================================ bridge / host commands
    wire            reset_n;
    wire    [31:0]  cmd_bridge_rd_data;
    wire            sd_ready, sd_ready_74;
synch_3 s_rdy74 (sd_ready, sd_ready_74, clk_74a);

// as the Jaguar core (K(J)): boot/setup wait for the SDRAM controller, not only the PLL
    wire            status_boot_done  = pll_locked_74 & sd_ready_74;
    wire            status_setup_done = pll_locked_74 & sd_ready_74;   // rising edge triggers the Ready-to-Run target command
    wire            status_running    = reset_n;

    wire            dataslot_requestread;
    wire    [15:0]  dataslot_requestread_id;
    wire            dataslot_requestread_ack = 1;
    wire            dataslot_requestread_ok = 1;

    wire            dataslot_requestwrite;
    wire    [15:0]  dataslot_requestwrite_id;
    wire    [31:0]  dataslot_requestwrite_size;
    wire            dataslot_requestwrite_ack = 1;
    wire            dataslot_requestwrite_ok = 1;

    wire            dataslot_update;
    wire    [15:0]  dataslot_update_id;
    wire    [31:0]  dataslot_update_size;

    wire            dataslot_allcomplete;

    wire     [31:0] rtc_epoch_seconds;
    wire     [31:0] rtc_date_bcd;
    wire     [31:0] rtc_time_bcd;
    wire            rtc_valid;

    wire            savestate_supported = 0;
    wire    [31:0]  savestate_addr = 0;
    wire    [31:0]  savestate_size = 0;
    wire    [31:0]  savestate_maxloadsize = 0;

    wire            savestate_start;
    wire            savestate_start_ack = 0;
    wire            savestate_start_busy = 0;
    wire            savestate_start_ok = 0;
    wire            savestate_start_err = 0;

    wire            savestate_load;
    wire            savestate_load_ack = 0;
    wire            savestate_load_busy = 0;
    wire            savestate_load_ok = 0;
    wire            savestate_load_err = 0;

    wire            osnotify_inmenu;

    wire            target_dataslot_read = 0;      // the core initiates no slot access
    wire            target_dataslot_write = 0;
    wire            target_dataslot_getfile = 0;
    wire            target_dataslot_openfile = 0;
    wire            target_dataslot_ack;
    wire            target_dataslot_done;
    wire    [2:0]   target_dataslot_err;
    wire    [15:0]  target_dataslot_id = 0;
    wire    [31:0]  target_dataslot_slotoffset = 0;
    wire    [31:0]  target_dataslot_bridgeaddr = 0;
    wire    [31:0]  target_dataslot_length = 0;
    wire    [31:0]  target_buffer_param_struct = 0;
    wire    [31:0]  target_buffer_resp_struct = 0;

    wire    [9:0]   datatable_addr = 10'd9;      // SM1.2: data.json slot index 4 (Save, id 10): entry 2 * 4 + 1 = its size
    wire            datatable_wren = 1'b1;
    wire    [31:0]  datatable_data = 32'd128;    // SM1.2: 64 x 16-bit 93C46 words
    wire    [31:0]  datatable_q;

    wire    [31:0]  eep_bridge_rd_data;          // SM1.2: Save slot read-back (sm_eep_bridge_rd below)
always @(*) begin
    casex (bridge_addr)
    default:      bridge_rd_data <= 0;
    32'h5xxxxxxx: bridge_rd_data <= eep_bridge_rd_data;   // SM1.2: Save slot (id 10)
    32'hF8xxxxxx: bridge_rd_data <= cmd_bridge_rd_data;
    endcase
end

core_bridge_cmd icb (
    .clk                ( clk_74a ),
    .reset_n            ( reset_n ),
    .bridge_endian_little   ( bridge_endian_little ),
    .bridge_addr            ( bridge_addr ),
    .bridge_rd              ( bridge_rd ),
    .bridge_rd_data         ( cmd_bridge_rd_data ),
    .bridge_wr              ( bridge_wr ),
    .bridge_wr_data         ( bridge_wr_data ),
    .status_boot_done       ( status_boot_done ),
    .status_setup_done      ( status_setup_done ),
    .status_running         ( status_running ),
    .dataslot_requestread       ( dataslot_requestread ),
    .dataslot_requestread_id    ( dataslot_requestread_id ),
    .dataslot_requestread_ack   ( dataslot_requestread_ack ),
    .dataslot_requestread_ok    ( dataslot_requestread_ok ),
    .dataslot_requestwrite      ( dataslot_requestwrite ),
    .dataslot_requestwrite_id   ( dataslot_requestwrite_id ),
    .dataslot_requestwrite_size ( dataslot_requestwrite_size ),
    .dataslot_requestwrite_ack  ( dataslot_requestwrite_ack ),
    .dataslot_requestwrite_ok   ( dataslot_requestwrite_ok ),
    .dataslot_update            ( dataslot_update ),
    .dataslot_update_id         ( dataslot_update_id ),
    .dataslot_update_size       ( dataslot_update_size ),
    .dataslot_allcomplete   ( dataslot_allcomplete ),
    .rtc_epoch_seconds      ( rtc_epoch_seconds ),
    .rtc_date_bcd           ( rtc_date_bcd ),
    .rtc_time_bcd           ( rtc_time_bcd ),
    .rtc_valid              ( rtc_valid ),
    .savestate_supported    ( savestate_supported ),
    .savestate_addr         ( savestate_addr ),
    .savestate_size         ( savestate_size ),
    .savestate_maxloadsize  ( savestate_maxloadsize ),
    .savestate_start        ( savestate_start ),
    .savestate_start_ack    ( savestate_start_ack ),
    .savestate_start_busy   ( savestate_start_busy ),
    .savestate_start_ok     ( savestate_start_ok ),
    .savestate_start_err    ( savestate_start_err ),
    .savestate_load         ( savestate_load ),
    .savestate_load_ack     ( savestate_load_ack ),
    .savestate_load_busy    ( savestate_load_busy ),
    .savestate_load_ok      ( savestate_load_ok ),
    .savestate_load_err     ( savestate_load_err ),
    .osnotify_inmenu        ( osnotify_inmenu ),
    .target_dataslot_read       ( target_dataslot_read ),
    .target_dataslot_write      ( target_dataslot_write ),
    .target_dataslot_getfile    ( target_dataslot_getfile ),
    .target_dataslot_openfile   ( target_dataslot_openfile ),
    .target_dataslot_ack        ( target_dataslot_ack ),
    .target_dataslot_done       ( target_dataslot_done ),
    .target_dataslot_err        ( target_dataslot_err ),
    .target_dataslot_id         ( target_dataslot_id ),
    .target_dataslot_slotoffset ( target_dataslot_slotoffset ),
    .target_dataslot_bridgeaddr ( target_dataslot_bridgeaddr ),
    .target_dataslot_length     ( target_dataslot_length ),
    .target_buffer_param_struct ( target_buffer_param_struct ),
    .target_buffer_resp_struct  ( target_buffer_resp_struct ),
    .datatable_addr         ( datatable_addr ),
    .datatable_wren         ( datatable_wren ),
    .datatable_data         ( datatable_data ),
    .datatable_q            ( datatable_q )
);

// ============================================================================================ slot bookkeeping (clk_74a)
// download-active and all-complete latches as the Jaguar core / S2; slot sizes latched per id from requestwrite.
    reg        allc_74 = 1'b0, dl_active_74 = 1'b0;
    reg [24:0] size1_74 = 25'd0, size2_74 = 25'd0, size3_74 = 25'd0, size4_74 = 25'd0;
always @(posedge clk_74a) begin
    if (dataslot_requestwrite) begin
        dl_active_74 <= 1'b1; allc_74 <= 1'b0;
        if (dataslot_requestwrite_id == 16'd1) size1_74 <= dataslot_requestwrite_size[24:0];
        if (dataslot_requestwrite_id == 16'd2) size2_74 <= dataslot_requestwrite_size[24:0];
        if (dataslot_requestwrite_id == 16'd3) size3_74 <= dataslot_requestwrite_size[24:0];   // SP
        if (dataslot_requestwrite_id == 16'd7) size4_74 <= dataslot_requestwrite_size[24:0];   // AU; rel: sound ROM = slot id 7 (id 4 = EEPROM default)
    end else if (dataslot_allcomplete) begin dl_active_74 <= 1'b0; allc_74 <= 1'b1; end
end
// into clk_ram. The sizes are quasi-static: written at each requestwrite, >= 1 s before allcomplete (they are only read
// once the 3-flop all-complete synchronizer below is high and the 1024-cycle quiet window has passed), so a plain
// two-register copy cannot be read while it changes. (A multi-bit crossing justified by this ordering, not by a FIFO.)
    reg [2:0]  allc_s = 3'b000;
    reg [24:0] size1_m = 25'd0, size1_r = 25'd0, size2_m = 25'd0, size2_r = 25'd0, size3_m = 25'd0, size3_r = 25'd0;   // SP: + slot 3
    reg [24:0] size4_m = 25'd0, size4_r = 25'd0;   // AU: slot 4
always @(posedge clk_ram) begin
    allc_s <= {allc_s[1:0], allc_74};
    size1_m <= size1_74; size1_r <= size1_m;
    size2_m <= size2_74; size2_r <= size2_m;
    size3_m <= size3_74; size3_r <= size3_m;
    size4_m <= size4_74; size4_r <= size4_m;
end

// ============================================================================================ APF loaders (clk_74a -> clk_sys)
    wire        l1_en, l2_en, l3_en;
    wire [24:0] l1_addr, l2_addr, l3_addr;
    wire [15:0] l1_data, l2_data, l3_data;
data_loader #(.ADDRESS_MASK_UPPER_4(4'h1), .ADDRESS_SIZE(25), .OUTPUT_WORD_SIZE(2)) slot1_loader (
    .clk_74a(clk_74a), .clk_memory(clk_sys), .bridge_wr(bridge_wr), .bridge_endian_little(bridge_endian_little),
    .bridge_addr(bridge_addr), .bridge_wr_data(bridge_wr_data),
    .write_en(l1_en), .write_addr(l1_addr), .write_data(l1_data));
data_loader #(.ADDRESS_MASK_UPPER_4(4'h2), .ADDRESS_SIZE(25), .OUTPUT_WORD_SIZE(2)) slot2_loader (
    .clk_74a(clk_74a), .clk_memory(clk_sys), .bridge_wr(bridge_wr), .bridge_endian_little(bridge_endian_little),
    .bridge_addr(bridge_addr), .bridge_wr_data(bridge_wr_data),
    .write_en(l2_en), .write_addr(l2_addr), .write_data(l2_data));
// SP: slot 3 = sprites.bin (16 MiB, bridge 0x3000_0000) -> SDRAM SDR_SPRITES_BASE 0x100_0000 (the s32_core p2 region)
data_loader #(.ADDRESS_MASK_UPPER_4(4'h3), .ADDRESS_SIZE(25), .OUTPUT_WORD_SIZE(2)) slot3_loader (
    .clk_74a(clk_74a), .clk_memory(clk_sys), .bridge_wr(bridge_wr), .bridge_endian_little(bridge_endian_little),
    .bridge_addr(bridge_addr), .bridge_wr_data(bridge_wr_data),
    .write_en(l3_en), .write_addr(l3_addr), .write_data(l3_data));
// AU3: slot 4 = sound.bin (4 MiB, bridge 0x4000_0000) -> d2_rom_psram (PSRAM chip 1, word address = byte offset / 2). ADDRESS_SIZE 22:
// rel (as SpidAudio1): the sound ROM is data slot id 7 at bridge 0x7000_0000 (nibble 7) for every game; nibble 4 / id 4
// is the universal EEPROM default slot. The l4_* / size4_* names are GA2Audio3's and are kept.
// the slot offset is 22 bits, so every write of this slot stays inside chip 1's words 0x000000-0x1FFFFF (die 0); none reaches SDRAM.
    wire        l4_en; wire [21:0] l4_addr; wire [15:0] l4_data;
data_loader #(.ADDRESS_MASK_UPPER_4(4'h7), .ADDRESS_SIZE(22), .OUTPUT_WORD_SIZE(2)) slot4_loader (   // rel: nibble 7
    .clk_74a(clk_74a), .clk_memory(clk_sys), .bridge_wr(bridge_wr), .bridge_endian_little(bridge_endian_little),
    .bridge_addr(bridge_addr), .bridge_wr_data(bridge_wr_data),
    .write_en(l4_en), .write_addr(l4_addr), .write_data(l4_data));

// ============================================================================================ U1 board configuration (clk_74a -> clk_sys)
// The game's 64-byte configuration file (APF data slot id 6, bridge 0x6000_0000; experiments/U1-universal/u1_cfg.py) selects the
// board at run time: descriptor (has_v25, has_ppi, sprite banks), input-wiring profile and the band's expected slot sums. The
// CPU reset stays asserted unless the file is complete, valid, and asks only for hardware this bitstream has (u1_board_cfg).
    wire        cf_en; wire [7:0] cf_addr; wire [15:0] cf_data;
data_loader #(.ADDRESS_MASK_UPPER_4(4'h6), .ADDRESS_SIZE(8), .OUTPUT_WORD_SIZE(2)) cfg_loader (
    .clk_74a(clk_74a), .clk_memory(clk_sys), .bridge_wr(bridge_wr), .bridge_endian_little(bridge_endian_little),
    .bridge_addr(bridge_addr), .bridge_wr_data(bridge_wr_data),
    .write_en(cf_en), .write_addr(cf_addr), .write_data(cf_data));
    wire        u1_seen, u1_ok, u1_has_v25, u1_has_ppi, u1_spr_valid; wire [3:0] u1_reason; wire [1:0] u1_spr_mask, u1_profile;
    wire        u1c_ok, u1c_has_v25, u1c_has_ppi, u1c_spr_valid; wire [1:0] u1c_spr_mask, u1c_profile;   // rel R: u1_board_cfg's raw outputs
    wire [31:0] u1_exp_sum0, u1_exp_fl0, u1_exp_sum1, u1_exp_fl1, u1_exp_sum2, u1_exp_fl2;
u1_board_cfg cfg (
    .clk(clk_sys), .ld_en(cf_en), .ld_addr(cf_addr), .ld_data(cf_data),
    .cfg_seen(u1_seen), .cfg_ok(u1c_ok), .reason(u1_reason),
    .has_v25(u1c_has_v25), .has_ppi(u1c_has_ppi), .sprite_bank_valid(u1c_spr_valid), .sprite_bank_mask(u1c_spr_mask), .profile(u1c_profile),
    .exp_sum0(u1_exp_sum0), .exp_fl0(u1_exp_fl0), .exp_sum1(u1_exp_sum1), .exp_fl1(u1_exp_fl1),
    .exp_sum2(u1_exp_sum2), .exp_fl2(u1_exp_fl2));
// rel R: the consumed outputs registered in clk_sys (u1_cfg_reg, top of this file); every consumer below uses the registered names
u1_cfg_reg cfgq (.clk(clk_sys), .ok_c(u1c_ok), .v25_c(u1c_has_v25), .ppi_c(u1c_has_ppi), .sprv_c(u1c_spr_valid), .sprm_c(u1c_spr_mask),
    .prof_c(u1c_profile), .ok(u1_ok), .v25(u1_has_v25), .ppi(u1_has_ppi), .sprv(u1_spr_valid), .sprm(u1_spr_mask), .prof(u1_profile));

// ============================================================================================ SM1.2 EEPROM persistence (clk_74a -> clk_sys)
// The 93C46's 64 words are an APF nonvolatile Save slot (id 10, bridge 0x5000_0000, 128 bytes, read back over the bridge when
// APF unloads the core) with an optional read-only factory-default image (id 4, bridge 0x4000_0000, 128 bytes). Both files use
// MAME's nvram/spidman/mainpcb_eeprom format: 64 little-endian 16-bit words, not inverted. data_loader (bridge_endian_little = 0)
// delivers each 16-bit word little-endian and sm_eep_bridge_rd returns it the same way, so words pass to and from the EEPROM's
// load / read ports unchanged; the EEPROM stores them inverted internally (s32_eeprom_ram: zero-filled RAM = erased FFFF).
// Selection: a save write always lands; a default write lands only while no save word has arrived, so the save wins in either
// load order, the default applies when the save file is missing, and with neither the EEPROM stays erased (the game then
// initialises it itself, slowly enough to lose its timer-0 race: the SM1.1 blocker). Every load ends before dataslot_allcomplete;
// the CPU reset waits for allcomplete + 1024 quiet clk_ram with no loader write (EEPROM writes included) + the slot read-back.
    wire        ed_en, es_en;
    wire  [7:0] ed_addr, es_addr;
    wire  [5:0] eu_addr;
    wire [15:0] ed_data, es_data, eep_rd_data;
data_loader #(.ADDRESS_MASK_UPPER_4(4'h4), .ADDRESS_SIZE(8), .OUTPUT_WORD_SIZE(2)) eepdef_loader (
    .clk_74a(clk_74a), .clk_memory(clk_sys), .bridge_wr(bridge_wr), .bridge_endian_little(bridge_endian_little),
    .bridge_addr(bridge_addr), .bridge_wr_data(bridge_wr_data),
    .write_en(ed_en), .write_addr(ed_addr), .write_data(ed_data));
data_loader #(.ADDRESS_MASK_UPPER_4(4'h5), .ADDRESS_SIZE(8), .OUTPUT_WORD_SIZE(2)) eepsave_loader (
    .clk_74a(clk_74a), .clk_memory(clk_sys), .bridge_wr(bridge_wr), .bridge_endian_little(bridge_endian_little),
    .bridge_addr(bridge_addr), .bridge_wr_data(bridge_wr_data),
    .write_en(es_en), .write_addr(es_addr), .write_data(es_data));
sm_eep_bridge_rd #(.ADDRESS_MASK_UPPER_4(4'h5), .RD_LAT(3)) eepsave_rd (   // not data_unloader: see the module header
    .clk_74a(clk_74a), .clk_sys(clk_sys), .bridge_rd(bridge_rd), .bridge_addr(bridge_addr),
    .bridge_rd_data(eep_bridge_rd_data), .eep_rd_addr(eu_addr), .eep_rd_data(eep_rd_data));
    reg         save_seen = 1'b0;
always @(posedge clk_sys) if (es_en) save_seen <= 1'b1;
    wire        eep_ld_wr   = es_en | (ed_en & ~save_seen);
    wire  [5:0] eep_ld_addr = es_en ? es_addr[6:1] : ed_addr[6:1];
    wire [15:0] eep_ld_data = es_en ? es_data : ed_data;

// ============================================================================================ SDRAM controller (upstream)
    wire        wr_req, wr_ack; wire [24:1] wr_addr; wire [15:0] wr_din; wire [1:0] wr_be;
    wire        p0_req, p0_burst, p0_ack; wire [24:1] p0_addr; wire [63:0] p0_dout;
    wire        p1_req, p1_ack; wire [24:3] p1_addr; wire [63:0] p1_dout;
    wire        p5_req, p5_ack; wire [24:3] p5_addr; wire [63:0] p5_dout;
    wire        sd_ncs_unused;
// AU3: Z80 sound-ROM port (core p3, clk_sys requester; upstream's p3 contract) -> d2_rom_psram rmps (below), not sp_sdram
    wire         au_p3_req, au_p3_ack; wire [24:1] au_p3_addr; wire [15:0] au_p3_dout;
// SP: sprite-ROM port (core p2) and the framebuffer client's fw / fr ports
    wire         sp_p2_req, sp_p2_ack; wire [24:4] sp_p2_addr; wire [127:0] sp_p2_dout;
    wire         sp_fb_wr_busy; wire [15:0] sp_fb_rd_pix;
    wire         fw_req, fw_fill, fw_valid, fw_last, fw_pop, fw_done; wire [24:10] fw_page;
    wire [8:0]   fw_c0, fw_c1, fw_col; wire [15:0] fw_data; wire [1:0] fw_be;
    wire         fr_req, fr_urgent, fr_dv, fr_done; wire [24:10] fr_page; wire [8:0] fr_c0, fr_dcol;
    wire [9:0]   fr_n; wire [15:0] fr_dout;
sp_sdram sdram (   // SP: experiments/SP-sprite-path/rtl/derived/sp_sdram.sv = upstream sdram.sv + sp_sdram.diff
    .clk(clk_ram), .init(~locked_r), .ready(sd_ready),
    .SDRAM_DQ(dram_dq), .SDRAM_A(dram_a), .SDRAM_BA(dram_ba),
    .SDRAM_DQML(dram_dqm[0]), .SDRAM_DQMH(dram_dqm[1]),
    .SDRAM_nCS(sd_ncs_unused), .SDRAM_nCAS(dram_cas_n), .SDRAM_nRAS(dram_ras_n), .SDRAM_nWE(dram_we_n), .SDRAM_CKE(dram_cke),
    .wr_req(wr_req), .wr_addr(wr_addr), .wr_din(wr_din), .wr_be(wr_be), .wr_ack(wr_ack),
    .p0_req(p0_req), .p0_burst(p0_burst), .p0_addr(p0_addr), .p0_dout(p0_dout), .p0_ack(p0_ack),
    .p1_req(p1_req), .p1_addr(p1_addr), .p1_dout(p1_dout), .p1_ack(p1_ack),
    .p2_req(sp_p2_req), .p2_addr(sp_p2_addr), .p2_dout(sp_p2_dout), .p2_ack(sp_p2_ack),
    .p3_req(1'b0), .p3_addr(24'd0), .p3_dout(), .p3_ack(),
    .p4_req(1'b0), .p4_addr(24'd0), .p4_dout(), .p4_ack(),
    .p5_req(p5_req), .p5_addr(p5_addr), .p5_dout(p5_dout), .p5_ack(p5_ack),
    .fw_req(fw_req), .fw_page(fw_page), .fw_fill(fw_fill), .fw_c0(fw_c0), .fw_c1(fw_c1),
    .fw_valid(fw_valid), .fw_col(fw_col), .fw_data(fw_data), .fw_be(fw_be), .fw_last(fw_last),
    .fw_pop(fw_pop), .fw_done(fw_done),
    .fr_req(fr_req), .fr_page(fr_page), .fr_c0(fr_c0), .fr_n(fr_n), .fr_urgent(fr_urgent),
    .fr_dv(fr_dv), .fr_dcol(fr_dcol), .fr_dout(fr_dout), .fr_done(fr_done)
);
// SDRAM clock pin: DDIO register pair clocked by clk_ram, high while clk_ram is low = clk_ram inverted (the 180-degree
// forwarded clock the S2 chip model and upstream's CL2 capture assume), as pocket_jaguar rtl/upstream/mem/sdram_dual.sv.
altddio_out #(
    .extend_oe_disable("OFF"), .intended_device_family("Cyclone V"), .invert_output("OFF"), .lpm_hint("UNUSED"),
    .lpm_type("altddio_out"), .oe_reg("UNREGISTERED"), .power_up_high("OFF"), .width(1)
) sdramclk_ddr (
    .datain_h(1'b0), .datain_l(1'b1), .outclock(clk_ram), .dataout(dram_clk),
    .aclr(1'b0), .aset(1'b0), .oe(1'b1), .outclocken(1'b1), .sclr(1'b0), .sset(1'b0)
);

// ============================================================================================ load queue, read-back, reset
    wire wq_empty;
    wire [31:0] wq_in, wq_out, wq_overflow, wq_collide; wire [15:0] wq_max_fill;
d2_load_wq3 wq (   // SP: three slot inputs
    .clk(clk_ram), .rst(~sd_ready),
    .a_en(l1_en), .a_addr(l1_addr), .a_data(l1_data),
    .b_en(l2_en), .b_addr(l2_addr), .b_data(l2_data),
    .c_en(l3_en), .c_addr(l3_addr), .c_data(l3_data),
    .a_base(SDR_MAINCPU_BASE), .b_base(SDR_TILES_BASE), .c_base(SDR_SPRITES_BASE),
    .wr_req(wr_req), .wr_addr(wr_addr), .wr_din(wr_din), .wr_be(wr_be), .wr_ack(wr_ack),
    .empty(wq_empty), .n_in(wq_in), .n_out(wq_out), .n_overflow(wq_overflow), .n_collide(wq_collide), .max_fill(wq_max_fill));

// "loaders idle": all-complete seen, queue empty and no loader write for 1024 clk_ram (as S2)
    reg [10:0] quiet = 11'd0;
always @(posedge clk_ram)
    if (!allc_s[2] || !wq_empty || l1_en || l2_en || l3_en || l4_en || ed_en || es_en || cf_en || wr_req) quiet <= 11'd0;   // U1: + EEPROM and configuration loads
    else if (!quiet[10]) quiet <= quiet + 1'd1;
    wire load_done = quiet[10] && sd_ready;

    wire        verify_done;
    wire [31:0] v_sum0, v_fl0, v_sum1, v_fl1, v_sum2, v_fl2, v_sum3, v_fl3, v_cycles;   // AU3: v_sum3 / v_fl3 = d2_rom_psram's read-back
d2_slot_verify3 ver (   // SP: + slot 3 (sprite ROM)
    .base2(SDR_SPRITES_BASE), .bytes2(size3_r), .sum2(v_sum2), .fl2(v_fl2),
       // word-serial form of S2's p1_slot_verify (same sums; D2 fit run 42126911324 timing)
    .clk(clk_ram), .rst(~sd_ready), .start(load_done),
    .base0(SDR_MAINCPU_BASE), .bytes0(size1_r), .base1(SDR_TILES_BASE), .bytes1(size2_r),
    .p5_req(p5_req), .p5_addr(p5_addr), .p5_dout(p5_dout), .p5_ack(p5_ack),
    .done(verify_done), .sum0(v_sum0), .fl0(v_fl0), .sum1(v_sum1), .fl1(v_fl1), .cycles(v_cycles));
// sums against the expected values carried by the game's configuration file (U1; static after the load)
    reg sums0_ok = 1'b0, sums1_ok = 1'b0, sums2_ok = 1'b0, sums3_ok = 1'b0;
always @(posedge clk_ram) begin
    sums0_ok <= verify_done && v_sum0 == u1_exp_sum0 && v_fl0 == u1_exp_fl0;
    sums1_ok <= verify_done && v_sum1 == u1_exp_sum1 && v_fl1 == u1_exp_fl1;
    sums2_ok <= verify_done && v_sum2 == u1_exp_sum2 && v_fl2 == u1_exp_fl2;   // SP: sprite ROM image
end

// CPU reset: held until the read-back is done, the host has released reset_n and the PLL is locked; video reset follows
// VIDEO_AFTER_RST clk_sys later (as S2).
    wire reset_n_s;
synch_3 s_rstn (reset_n, reset_n_s, clk_sys);
    reg  [1:0]  vd_s = 2'b00;
always @(posedge clk_sys) vd_s <= {vd_s[0], verify_done};
    reg         rst_r = 1'b1, vrst_r = 1'b1;
    wire        wv_clear_done, wv_wd_rd, wv_wd_wr;   // AU: d2_wave_psram status (below)
    wire        wv_tpu_ok, wv_busy, wv_acc_tgl; wire [15:11] wv_clr_idx;   // AU2: d2_wave_psram observation (band only)
    wire        rp_vf_done, rp_wd_p3, rp_ld_ovf, rp_wq_empty, rp_tpu_ok, rp_acc_tgl, rp_busy;   // AU3: d2_rom_psram status (below)
// AU2 diagnostic fallback: if the wave-RAM clear is not done WCLR_TIMEOUT clk_sys (100 ms) after PLL lock, rst_r stops waiting
// for it (band cell 17 stays red, cell 29 shows the timeout). The counter stops when the clear is done first, so the normal
// path is unchanged (the clear takes about 4.3 ms).
    localparam integer WCLR_TIMEOUT = 4831731;   // 100 ms at 48.317 MHz
    reg  [22:0] wclr_cnt = 23'd0; reg wclr_to = 1'b0;
always @(posedge clk_sys)
    if (!locked_s) begin wclr_cnt <= 23'd0; wclr_to <= 1'b0; end
    else if (!wv_clear_done && !wclr_to) begin
        if (wclr_cnt == 23'(WCLR_TIMEOUT - 1)) wclr_to <= 1'b1; else wclr_cnt <= wclr_cnt + 23'd1;
    end
    reg  [31:0] vcnt_r = 32'd0;
always @(posedge clk_sys) begin
    if (!vd_s[1] || !reset_n_s || !locked_s || !(wv_clear_done || wclr_to) || !rp_vf_done || !u1_ok) begin rst_r <= 1'b1; vrst_r <= 1'b1; vcnt_r <= 32'd0; end   // AU: + wave-RAM clear (AU2: or timeout); AU3: + the PSRAM sound-ROM read-back; U1: + valid configuration
    else begin
        rst_r <= 1'b0;
        if (vcnt_r < VIDEO_AFTER_RST) vcnt_r <= vcnt_r + 32'd1; else vrst_r <= 1'b0;
    end
end

// ============================================================================================ RC1: pause on the Pocket menu
// osnotify_inmenu (core_bridge_cmd, clk_74a, set / cleared by host command 0x00B0, 0 after bridge reset) -> clk_sys. clk_74a is an
// asynchronous clock group (d2_core_constraints.sdc), as for the controller keys.
    reg        menu_m = 1'b0, menu_s = 1'b0, pause_r = 1'b0;
always @(posedge clk_sys) begin menu_m <= osnotify_inmenu; menu_s <= menu_m; pause_r <= menu_s; end

// ============================================================================================ ce_cpu
// CE_MODE 1: upstream's accumulator +21848/65536 (Arcade-SegaSystem32.sv cpu_ce_inc for GA2; the hardware-proven bus
// cadence, plan section 3). CE_MODE 0: exactly every third clk_sys (WC-sim / S2 baseline run s2c).
    reg [1:0]  c3 = 2'd0;
    reg        ce_div3 = 1'b0;
    reg [15:0] acc_cpu = 16'd0;
    reg        ce_acc = 1'b0;
always @(posedge clk_sys) begin
    c3 <= (c3 == 2'd2) ? 2'd0 : c3 + 2'd1;
    ce_div3 <= (c3 == 2'd2);
    if (rst_r) begin ce_acc <= 1'b0; acc_cpu <= 16'd0; end
    else begin {ce_acc, acc_cpu} <= {1'b0, acc_cpu} + 17'd21848; if (pause_r) ce_acc <= 1'b0; end   // RC1: gated, NCO runs on
    if (pause_r) ce_div3 <= 1'b0;   // RC1 (CE_MODE 0, simulation only)
end
    wire ce_cpu = (CE_MODE != 0) ? ce_acc : ce_div3;

// ============================================================================================ audio clock enables (AU)
// upstream s32_audio_ce, unmodified, connected as Arcade-SegaSystem32.sv:339-342 (reset = the board reset, FM free-running from
// PLL lock); D2 has no pause, so the enables go to the core directly. clk_sys = 48.317 MHz = upstream's, so every rate is upstream's.
// RC1: the enables are gated by pause_r as upstream's ce_*_run (the NCOs keep running behind the gates).
    wire ce_z80_n, ce_fm_n, ce_pcm_n;
s32_audio_ce audio_ce (
    .clk(clk_sys), .reset(rst_r), .pll_locked(locked_s),
    .is_multi32(1'b0), .ce_z80(ce_z80_n), .ce_fm(ce_fm_n), .ce_pcm(ce_pcm_n));
    wire ce_z80 = ce_z80_n & ~pause_r, ce_fm = ce_fm_n & ~pause_r, ce_pcm = ce_pcm_n & ~pause_r;

// ============================================================================================ SRAM work-RAM port
    wire [15:0] wx_addr, wx_wdata, wx_q; wire [1:0] wx_be; wire wx_we, wx_rd, wx_rdy;
    wire [15:0] sram_dq_o; wire sram_dq_oe, sram_sample_now;
    wire [31:0] sram_reads, sram_writes, sram_overlap;
d2_sram_port sram_port (
    .clk(clk_sys), .rd_edges(3'(RD_EDGES)), .rst(rst_r), .addr(wx_addr), .wdata(wx_wdata), .be(wx_be), .we(wx_we),
    .rd(wx_rd), .q(wx_q), .rdy(wx_rdy),
    .sram_a(sram_a), .sram_dq_o(sram_dq_o), .sram_dq_oe(sram_dq_oe), .sram_dq_i(sram_dq),
    .sram_oe_n(sram_oe_n), .sram_we_n(sram_we_n), .sram_ub_n(sram_ub_n), .sram_lb_n(sram_lb_n),
    .sample_now(sram_sample_now), .n_reads(sram_reads), .n_writes(sram_writes), .overlap(sram_overlap));
assign sram_dq = sram_dq_oe ? sram_dq_o : 16'hZZZZ;

// ============================================================================================ the core
    board_desc_t run_board;   // U1: the run-time board descriptor (configuration slot, u1_board_cfg); fields outside the U1
                              // scope stay constant 0, so synthesis still removes the upstream blocks they gate
always_comb begin
    run_board                   = '0;
    run_board.has_v25           = u1_has_v25;
    run_board.has_ppi           = u1_has_ppi;
    run_board.sprite_bank_valid = u1_spr_valid;
    run_board.sprite_bank_mask  = u1_spr_mask;
end
    wire [7:0] adc_ch [0:7];
genvar gi;
generate for (gi = 0; gi < 8; gi = gi + 1) begin : g_adc
    assign adc_ch[gi] = 8'h80;
end endgenerate

    wire         c_p2_req, c_p4_req, c_p5_req, c_wave_req, c_fb_er_req, c_fb_rd_req;   // AU: p3 = au_p3_* (above)
    wire         c_p2_ack, c_p4_ack, c_p5_ack, c_wave_ack, c_fb_er_ack, c_fb_rd_ack;
    wire [24:4]  c_p2_addr_u; wire [24:1] c_p4_addr_u, c_wave_addr_u; wire [24:3] c_p5_addr_u;
    wire [15:0]  c_p4_dout;   // AU: wave read data from d2_wave_psram
    wire [15:0]  c_wave_data_u; wire [1:0] c_wave_be_u;
    wire         fb_wr_start_u, fb_wr_valid_u, fb_wr_end_u, fb_wr_shadow_u;
    wire [1:0]   fb_wr_buf_u, fb_er_buf_u, fb_rd_buf_u; wire [8:0] fb_wr_x_u, fb_rd_x_u; wire [7:0] fb_wr_y_u, fb_er_y_u, fb_rd_y_u;
    wire [15:0]  fb_wr_pix_u;
    wire [23:0]  rgb_a, rgb_b_unused;
    wire         ce_pix, hs, vs, hb, vb, mode_416_active;
    wire         eep_modified_unused, wheel_unused;
    wire signed [15:0] core_audio_l, core_audio_r;   // AU: s32_audio_mix output
    wire         irq_ack_v2;
    wire [15:0]  spr_oow_wr, spr_oow_rd, spr_oow_eng;   // SP
    wire [95:0]  dbg_v2; wire [63:0] dbg_bus;           // GA2Play5 freeze readout (observation)
    wire [7:0]   irq_vec;

// ============================================================================================ controls (D2-play)
// See module u1_controls (top of this file).
    wire  [7:0] g_p1a, g_p2a, g_ppa, g_ppb, g_svc12, g_ppi_pc;   // 2P: + g_p2a; 4P: + g_ppa / g_ppb
u1_controls ctl (.clk(clk_sys), .key(cont1_key[15:0]), .key2(cont2_key), .key3(cont3_key), .key4(cont4_key),   // rel: profile + guard
    .profile(u1_profile), .hold(pause_r),
    .p1a(g_p1a), .p2a(g_p2a), .ppa(g_ppa), .ppb(g_ppb), .svc12(g_svc12), .ppi_pc(g_ppi_pc));

s32_core core (
    .clk_sys(clk_sys), .clk_ram(clk_ram), .clk_v25(clk_v25),
    .rst(rst_r), .video_rst(vrst_r),
    .board(run_board),   // U1
    .ce_cpu(ce_cpu), .ce_z80(ce_z80), .ce_fm(ce_fm), .ce_pcm(ce_pcm),   // AU: upstream s32_audio_ce
    .pause(pause_r),   // RC1: upstream's pause input (V60 exec cadence, V25 domain)
    .fast_v60(1'b1),
    .sdr_p0_req(p0_req), .sdr_p0_burst(p0_burst), .sdr_p0_addr(p0_addr), .sdr_p0_dout(p0_dout), .sdr_p0_ack(p0_ack),
    .sdr_p1_req(p1_req), .sdr_p1_addr(p1_addr), .sdr_p1_dout(p1_dout), .sdr_p1_ack(p1_ack),
    .sdr_p2_req(sp_p2_req), .sdr_p2_addr(sp_p2_addr), .sdr_p2_dout(sp_p2_dout), .sdr_p2_ack(sp_p2_ack),   // SP
    .sdr_p3_req(au_p3_req), .sdr_p3_addr(au_p3_addr), .sdr_p3_dout(au_p3_dout), .sdr_p3_ack(au_p3_ack),   // AU: sp_sdram p3
    .sdr_p4_req(c_p4_req), .sdr_p4_addr(c_p4_addr_u), .sdr_p4_dout(c_p4_dout), .sdr_p4_ack(c_p4_ack),     // AU: d2_wave_psram
    .sdr_wave_wr_req(c_wave_req), .sdr_wave_wr_addr(c_wave_addr_u),
    .sdr_wave_wr_data(c_wave_data_u), .sdr_wave_wr_be(c_wave_be_u), .sdr_wave_wr_ack(c_wave_ack),
    .sdr_p5_req(c_p5_req), .sdr_p5_addr(c_p5_addr_u), .sdr_p5_dout(64'd0), .sdr_p5_ack(c_p5_ack),
    .fb_wr_start(fb_wr_start_u), .fb_wr_buf(fb_wr_buf_u), .fb_wr_x(fb_wr_x_u), .fb_wr_y(fb_wr_y_u),
    .fb_wr_valid(fb_wr_valid_u), .fb_wr_pix(fb_wr_pix_u), .fb_wr_end(fb_wr_end_u),
    .fb_wr_shadow(fb_wr_shadow_u), .fb_wr_busy(sp_fb_wr_busy),   // SP
    .fb_er_req(c_fb_er_req), .fb_er_buf(fb_er_buf_u), .fb_er_y(fb_er_y_u), .fb_er_ack(c_fb_er_ack),
    .fb_rd_req(c_fb_rd_req), .fb_rd_buf(fb_rd_buf_u), .fb_rd_y(fb_rd_y_u), .fb_rd_ack(c_fb_rd_ack),
    .fb_rd_x(fb_rd_x_u), .fb_rd_pix(sp_fb_rd_pix),   // SP
    .wram_ext_addr(wx_addr), .wram_ext_wdata(wx_wdata), .wram_ext_be(wx_be), .wram_ext_we(wx_we), .wram_ext_rd(wx_rd),
    .wram_ext_q(wx_q), .wram_ext_rdy(wx_rdy),
    .dbg_irq_ack(irq_ack_v2), .dbg_irq_vector(irq_vec),
    .dbg_spr_oow_wr(spr_oow_wr), .dbg_spr_oow_rd(spr_oow_rd), .dbg_spr_oow_eng(spr_oow_eng),   // SP (observation)
    .dbg_v2(dbg_v2), .dbg_bus(dbg_bus),   // GA2Play5 freeze readout (observation)
    .v25_prg_wr(1'b0), .v25_prg_waddr(16'd0), .v25_prg_wdata(8'd0),
    .eep_ld_wr(eep_ld_wr), .eep_ld_addr(eep_ld_addr), .eep_ld_data(eep_ld_data),   // SM1.2: Save / default slots (EEPROM persistence)
    .eep_rd_data(eep_rd_data), .eep_rd_addr(eu_addr),
    .eep_upload(1'b0), .eep_modified(eep_modified_unused),
    .in_p1a(g_p1a), .in_p2a(g_p2a), .in_portc(8'hff),   // 2P: player 2 = Pocket controller 2
    .in_svc12(g_svc12), .in_svc34(8'hff),
    .in_p1b(8'hff), .in_p2b(8'hff),
    .in_portc_b(8'hff), .in_svc12_b(8'hff), .in_svc34_b(8'hff),
    .adc_ch(adc_ch),
    .track_p1_x(8'd0), .track_p1_y(8'd0), .track_p2_x(8'd0), .track_p2_y(8'd0),
    .track_p3_x(8'd0), .track_p3_y(8'd0),
    .track_p1_dir(4'd0), .track_p2_dir(4'd0), .track_p3_dir(4'd0),
    .track_mouse_dx(9'sd0), .track_mouse_dy(9'sd0), .track_mouse_strobe(1'b0),
    .trackball_y_invert(1'b0),
    .ppi_pa(g_ppa), .ppi_pb(g_ppb), .ppi_pc(g_ppi_pc),   // 4P: players 3 / 4 = Pocket controllers 3 / 4
    .rgb_a(rgb_a), .rgb_b(rgb_b_unused),
    .ce_pix(ce_pix),
    .hs(hs), .vs(vs), .hb(hb), .vb(vb),
    .mode_416_active(mode_416_active),
    .audio_l(core_audio_l), .audio_r(core_audio_r),   // AU
    .out_lamps(),
    .wheel_load_ch0(wheel_unused)
);

// client ports not served from memory (latency / hold as the S2 C++ stubs: 10 clk_ram for p2-p5, 4 for wave/framebuffer)
    wire [15:0] n_p5;
d2_ack_stub #(.LAT(10)) st_p5 (.clk(clk_ram), .rst(rst_r), .req(c_p5_req),    .ack(c_p5_ack),    .n_req(n_p5));
// AU: the RF5C68 wave RAM in PSRAM chip 0 (rtl/d2_wave_psram.sv; clk_sys, the RF5C68's own domain; 4-phase req / ack).
// Its clear (32K words of 0 = logical 0xFF, inverted storage) starts at PLL lock; rst_r waits for clear_done (above).
d2_wave_psram wvps (
    .clk(clk_sys), .rst(!locked_s),
    .sdr_p4_req(c_p4_req), .sdr_p4_addr(c_p4_addr_u), .sdr_p4_dout(c_p4_dout), .sdr_p4_ack(c_p4_ack),
    .sdr_wave_wr_req(c_wave_req), .sdr_wave_wr_addr(c_wave_addr_u), .sdr_wave_wr_data(c_wave_data_u),
    .sdr_wave_wr_be(c_wave_be_u), .sdr_wave_wr_ack(c_wave_ack),
    .clear_done(wv_clear_done), .wd_rd(wv_wd_rd), .wd_wr(wv_wd_wr),
    .cram_a(cram0_a), .cram_dq(cram0_dq), .cram_wait(cram0_wait), .cram_clk(cram0_clk), .cram_adv_n(cram0_adv_n),
    .cram_cre(cram0_cre), .cram_ce0_n(cram0_ce0_n), .cram_ce1_n(cram0_ce1_n), .cram_oe_n(cram0_oe_n), .cram_we_n(cram0_we_n),
    .cram_ub_n(cram0_ub_n), .cram_lb_n(cram0_lb_n),
    .dbg_tpu_ok(wv_tpu_ok), .dbg_clr_idx(wv_clr_idx), .dbg_acc_tgl(wv_acc_tgl), .dbg_busy(wv_busy));   // AU2: band only
// AU3: the Z80 sound ROM in PSRAM chip 1 (rtl/d2_rom_psram.sv; clk_sys, the requester's own domain; 4-phase p3 req / ack). It takes
// the slot-4 loader's words, reads the slot back once the loaders are idle (load_done, the same start as the SDRAM read-back of
// slots 1-3; the CPU reset waits for rp_vf_done), then serves s32_core's p3 port.
    reg  [1:0]  ld_s = 2'b00;   // load_done (clk_ram) into clk_sys
// rel (rel_derive.py X): the read-back size into clk_sys straight from its clk_74a latch, the quasi-static slot-size crossing of
// the clk_ram copies above (asynchronous clock groups, SDC A1; written at requestwrite, sampled by rmps only at vf_start, after the
// all-complete synchroniser, the quiet window and ld_s). Replaces RC1's timed clk_ram -> clk_sys path size4_r -> rmps vf_n.
    reg [24:0] size4_sm = 25'd0, size4_sys = 25'd0;
always @(posedge clk_sys) begin size4_sm <= size4_74; size4_sys <= size4_sm; end
always @(posedge clk_sys) ld_s <= {ld_s[0], load_done};
d2_rom_psram rmps (
    .clk(clk_sys), .rst(!locked_s),
    .ld_en(l4_en), .ld_addr(l4_addr), .ld_data(l4_data),
    .vf_start(ld_s[1]), .vf_bytes(size4_sys), .vf_done(rp_vf_done), .vf_sum(v_sum3), .vf_fl(v_fl3),   // rel: clk_sys copy (X)
    .sdr_p3_req(au_p3_req), .sdr_p3_addr(au_p3_addr), .sdr_p3_dout(au_p3_dout), .sdr_p3_ack(au_p3_ack),
    .wd_p3(rp_wd_p3), .ld_ovf(rp_ld_ovf), .wq_empty(rp_wq_empty),
    .cram_a(cram1_a), .cram_dq(cram1_dq), .cram_wait(cram1_wait), .cram_clk(cram1_clk), .cram_adv_n(cram1_adv_n),
    .cram_cre(cram1_cre), .cram_ce0_n(cram1_ce0_n), .cram_ce1_n(cram1_ce1_n), .cram_oe_n(cram1_oe_n), .cram_we_n(cram1_we_n),
    .cram_ub_n(cram1_ub_n), .cram_lb_n(cram1_lb_n),
    .dbg_tpu_ok(rp_tpu_ok), .dbg_acc_tgl(rp_acc_tgl), .dbg_busy(rp_busy));   // AU3: observation only
// AU3: sound-ROM sums against the expected values (clk_sys; the d2_slot_verify4 comparison of the au top, moved to rmps's domain)
always @(posedge clk_sys) sums3_ok <= 1'b0;   // rel: no expected sound-ROM sums (band only, BAND_EN 0; rel_derive.py S)
// AU: request-edge counters of the ports the stubs used to count (observation only; unconnected in synthesis, pruned)
    reg [15:0] n_p3 = 16'd0, n_p4 = 16'd0, n_wave = 16'd0; reg p3q_d = 1'b0, p4q_d = 1'b0, wvq_d = 1'b0;
always @(posedge clk_sys) begin
    p3q_d <= au_p3_req; p4q_d <= c_p4_req; wvq_d <= c_wave_req;
    if (au_p3_req && !p3q_d) n_p3 <= n_p3 + 16'd1;
    if (c_p4_req && !p4q_d) n_p4 <= n_p4 + 16'd1;
    if (c_wave_req && !wvq_d) n_wave <= n_wave + 16'd1;
end
// AU: audio out (plan 3b): the combinational s32_audio_mix output is registered once per ce_fm (8.054 MHz, a clk_sys strobe),
// so the /10 shift-add tree ends in this register and sound_i2s's change detector / dcfifo see one settled value per update;
// sound_i2s (MIT, agg23; as pocket_jaguar core_top.sv:1020-1031) resamples nearest-neighbour to 48 kHz on clk_74a (decision D5).
// Timing (CI run 43657433253): two free-running clk_sys pipeline registers in front of the ce_fm register give the register
// retimer registers to place inside the /10 tree (with the mixer-input registers of s32_soundsys_d2_au.sv: +3 clk_sys of latency,
// sample values unchanged). No timing exception.
    reg signed [15:0] aud_l_p1 = 16'sd0, aud_r_p1 = 16'sd0, aud_l_p2 = 16'sd0, aud_r_p2 = 16'sd0;
    reg signed [15:0] aud_l_r = 16'sd0, aud_r_r = 16'sd0;
always @(posedge clk_sys) begin aud_l_p1 <= core_audio_l; aud_r_p1 <= core_audio_r; aud_l_p2 <= aud_l_p1; aud_r_p2 <= aud_r_p1; end
// RC1: the output register keeps the ungated ce_fm cadence and loads 0 while paused (upstream: AUDIO = pause ? 0 : aud).
always @(posedge clk_sys) if (ce_fm_n) begin aud_l_r <= pause_r ? 16'sd0 : aud_l_p2; aud_r_r <= pause_r ? 16'sd0 : aud_r_p2; end
sound_i2s #(
    .CHANNEL_WIDTH ( 16 ),
    .SIGNED_INPUT  ( 1 )
) sound_i2s (
    .clk_74a    ( clk_74a ),
    .clk_audio  ( clk_sys ),
    .audio_l    ( aud_l_r ),
    .audio_r    ( aud_r_r ),
    .audio_mclk ( audio_mclk ),
    .audio_lrck ( audio_lrck ),
    .audio_dac  ( audio_dac )
);

// SP: sprite framebuffer in SDRAM (experiments/SP-sprite-path/rtl/sp_fb_sdram.sv, s32_fb_if drop-in), 4 slots x 256 KB at
// 0x0C0_0000; line fetch width follows the CRT mode (320 / 416). p2 (sprite ROM) is served by sp_sdram above.
    wire [15:0] fb_n_shadow_drop, fb_n_erase_skip, fb_n_erase_fill, fb_n_late_publish; wire fb_init_busy;
sp_fb_sdram #(.FB_BASE(25'h0C0_0000)) spfb (
    .clk(clk_ram), .rst(rst_r), .scan_wide(mode_416_active),
    .wr_start(fb_wr_start_u), .wr_buf(fb_wr_buf_u), .wr_x(fb_wr_x_u), .wr_y(fb_wr_y_u),
    .wr_valid(fb_wr_valid_u), .wr_pix(fb_wr_pix_u), .wr_end(fb_wr_end_u), .wr_shadow(fb_wr_shadow_u), .wr_busy(sp_fb_wr_busy),
    .er_req(c_fb_er_req), .er_buf(fb_er_buf_u), .er_y(fb_er_y_u), .er_ack(c_fb_er_ack),
    .rd_req(c_fb_rd_req), .rd_buf(fb_rd_buf_u), .rd_y(fb_rd_y_u), .rd_ack(c_fb_rd_ack),
    .rd_x(fb_rd_x_u), .rd_pix(sp_fb_rd_pix),
    .fw_req(fw_req), .fw_page(fw_page), .fw_fill(fw_fill), .fw_c0(fw_c0), .fw_c1(fw_c1),
    .fw_valid(fw_valid), .fw_col(fw_col), .fw_data(fw_data), .fw_be(fw_be), .fw_last(fw_last),
    .fw_pop(fw_pop), .fw_done(fw_done),
    .fr_req(fr_req), .fr_page(fr_page), .fr_c0(fr_c0), .fr_n(fr_n), .fr_urgent(fr_urgent),
    .fr_dv(fr_dv), .fr_dcol(fr_dcol), .fr_dout(fr_dout), .fr_done(fr_done),
    .n_shadow_drop(fb_n_shadow_drop), .n_erase_skip(fb_n_erase_skip), .n_erase_fill(fb_n_erase_fill),
    .n_late_publish(fb_n_late_publish), .init_busy(fb_init_busy));
// request-edge counters of the ports the stubs used to count (observation only; unconnected in synthesis, pruned)
    reg [15:0] n_p2 = 16'd0, n_fb_er = 16'd0, n_fb_rd = 16'd0; reg p2q_d = 1'b0, erq_d = 1'b0, rdq_d = 1'b0;
always @(posedge clk_ram) begin
    p2q_d <= sp_p2_req; erq_d <= c_fb_er_req; rdq_d <= c_fb_rd_req;
    if (sp_p2_req && !p2q_d) n_p2 <= n_p2 + 16'd1;
    if (c_fb_er_req && !erq_d) n_fb_er <= n_fb_er + 16'd1;
    if (c_fb_rd_req && !rdq_d) n_fb_rd <= n_fb_rd + 16'd1;
end

// ============================================================================================ video
    wire [23:0] vid_rgb_pre;
    wire        vid_de, vid_skip, vid_hs, vid_vs, vid_fallback;
    wire [15:0] vid_blank_lines;
ga2_video vbridge (
    .clk_sys(clk_sys), .ce_pix(ce_pix), .rgb(rgb_a), .hs(hs), .vs(vs), .hblank(hb), .vblank(vb),
    .clk_vid(clk_vid), .video_rgb(vid_rgb_pre), .video_de(vid_de), .video_skip(vid_skip),
    .video_hs(vid_hs), .video_vs(vid_vs), .fallback(vid_fallback), .n_blank_lines(vid_blank_lines));

// diagnostic band inputs: V2 acknowledges of the per-frame interrupt (IRQ 64 = vector 0x00 on this board) and a
// heartbeat from the CPU's work-RAM traffic (V2's retirement is internal to the unmodified v2_core and not a port)
    reg  [7:0]  irq64_cnt = 8'd0;
    reg         irq_ack_d = 1'b0;
    reg  [23:0] wram_acc = 24'd0;
    reg         wx_rd_d = 1'b0, wx_we_d = 1'b0;
always @(posedge clk_sys) begin
    irq_ack_d <= irq_ack_v2; wx_rd_d <= wx_rd; wx_we_d <= wx_we;
    if (rst_r) begin irq64_cnt <= 8'd0; wram_acc <= 24'd0; end
    else begin
        if (irq_ack_v2 && !irq_ack_d && irq_vec == 8'h00) irq64_cnt <= irq64_cnt + 8'd1;
        if ((wx_rd && !wx_rd_d) || (wx_we && !wx_we_d)) wram_acc <= wram_acc + 24'd1;
    end
end
    wire band_px, diag_px, ro_px; wire [23:0] diag_rgb;   // GA2Play5: ga2_video -> d2_diag_band -> d2_freeze_band -> pins
d2_diag_band_au3 #(.ROW0(BAND_ROW0)) band (   // AU: + cells 16-29; AU3: + 30-31, cell 16 follows the PSRAM read-back
    .clk_vid(clk_vid), .en(BAND_EN != 0),
    .rgb_in(vid_rgb_pre), .de(vid_de), .skip(vid_skip), .vs(vid_vs), .rgb_out(diag_rgb), .in_band(diag_px),
    .pll_locked(pll_locked), .sdram_ready(sd_ready), .all_complete(allc_s[2]), .verify_done(verify_done),
    .sums0_ok(sums0_ok), .sums1_ok(sums1_ok && sums2_ok),   // SP: band cell 5 = tile sums AND sprite sums
     .cpu_running(!rst_r), .heartbeat(wram_acc[HB_BIT]), .irq64(irq64_cnt),
    .snd_sums_ok(sums3_ok), .psram_clear_done(wv_clear_done), .wave_wd_rd(wv_wd_rd), .wave_wd_wr(wv_wd_wr),   // AU
    .wv_rst_low(locked_s), .wv_tpu_ok(wv_tpu_ok), .wv_busy(wv_busy), .wv_acc_tgl(wv_acc_tgl), .wclr_timeout(wclr_to),
    .wv_clr_idx(wv_clr_idx),   // AU2
    .snd_verify_done(rp_vf_done), .rom_wd_p3(rp_wd_p3), .rom_ld_ovf(rp_ld_ovf));   // AU3
// GA2Play5 freeze readout (rtl/d2_freeze_readout.sv): one text line over DE lines BAND_ROW0-9 .. BAND_ROW0-1 (211-219), x 1-318:
// PC, state (RUN / TRP / BUS / FCH / LOP / RST), micro-PC, data access + direction, fetch address, handshake flags, opcode
// bytes, time since the last dispatch. Display only; the snapshot is taken once per frame on clk_sys and two-flop
// synchronised per bit into clk_vid.
    wire        ro_tgl, ro_we; wire [2:0] ro_st; wire [11:0] ro_upc; wire [23:0] ro_pc, ro_da, ro_fa;
    wire  [7:0] ro_fl, ro_age; wire [31:0] ro_op;
d2_freeze_cap rocap (
    .clk(clk_sys), .rst(rst_r), .v2(dbg_v2), .bus(dbg_bus), .p0_req(p0_req), .p0_ack(p0_ack), .sram_rd(wx_rd), .sram_rdy(wx_rdy),
    .frame_tgl(ro_tgl), .s_pc(ro_pc), .s_st(ro_st), .s_upc(ro_upc), .s_we(ro_we), .s_da(ro_da), .s_fa(ro_fa), .s_fl(ro_fl),
    .s_op(ro_op), .s_age(ro_age));
d2_freeze_band #(.ROW0(BAND_ROW0 - 9)) roband (
    .clk_vid(clk_vid), .en(BAND_EN != 0),
    .rgb_in(diag_rgb), .de(vid_de), .skip(vid_skip), .vs(vid_vs), .rgb_out(video_rgb), .in_ro(ro_px), .frame_tgl(ro_tgl),
    .pc(ro_pc), .st(ro_st), .upc(ro_upc), .we(ro_we), .da(ro_da), .fa(ro_fa), .fl(ro_fl), .op(ro_op), .age(ro_age));
assign band_px = diag_px | ro_px;   // observation: band or readout pixel

assign video_rgb_clock    = clk_vid;
assign video_rgb_clock_90 = clk_vid_90;
assign video_de   = vid_de;
assign video_skip = vid_skip;
assign video_hs   = vid_hs;
assign video_vs   = vid_vs;

endmodule

`default_nettype wire
